css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .calc-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px 30px;}
.mz .resp-fila{display: flex; align-items: center; gap: 8px; font-size: 19px; font-weight: 700; font-family: sans-serif; flex-wrap: wrap;}
.mz .caja{width: 50px; height: 34px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -4px 0 9px;}
.mz .tabla-dm{width: 100%; border-collapse: collapse; font-family: sans-serif;}
.mz .tabla-dm th,.mz .tabla-dm td{border: 1.6px solid var(--bosque); text-align: center; padding: 9px 4px; font-size: 17px; font-weight: 700;}
.mz .tabla-dm th{background: #eee; font-size: 14px;}
.mz .tabla-dm .dado{background: #f3f3f3;}
